218	        mockMvc.perform(get("/api/equipment/eq-par/readings"))
219	                .andExpect(jsonPath("$.length()").value(threads));
220	        mockMvc.perform(get("/api/equipment/eq-par/status"))
221	                .andExpect(jsonPath("$.version").value(1 + threads));
222	    }
223	}
