package com.example.starter.maintenance.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 通用配置：提供可替换的 UTC 时钟，便于时间相关测试使用可控时钟。
 */
@Configuration
public class MaintenanceConfig {

    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.maintenance.domain;

/**
 * 设备。
 *
 * @param equipmentId               设备唯一标识
 * @param maintenancePeriodMinutes  保养周期（分钟），登记后不可修改
 * @param version                   设备版本号，初始 1，每次写操作校验并加一
 */
public record Equipment(String equipmentId, long maintenancePeriodMinutes, long version) {
}

package com.example.starter.maintenance.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 完成保养请求：以某现存读数及其当前修订号为锚点，锚点时间须严格晚于上次保养锚点。
 *
 * @param requestId         全局唯一请求标识（幂等键）
 * @param expectedVersion   设备期望版本号，与当前版本不一致时返回 409
 * @param readingId         锚点读数标识，须已存在
 * @param anchorRevisionNo  锚点读数的当前修订号，与当前修订号不一致时返回 409
 */
public record CompleteMaintenanceRequest(
        @NotBlank String requestId,
        @NotNull Long expectedVersion,
        @NotBlank String readingId,
        @NotNull @Positive Integer anchorRevisionNo) {
}

