    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    decided_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT uq_deferral_key UNIQUE (equipment_id, defer_key)
);
CREATE INDEX IF NOT EXISTS idx_deferral_equipment ON deferral (equipment_id, cycle_no, status);
COMMENT ON TABLE deferral IS '保养延期记录：同一设备同时仅允许一条 PENDING；批准后阈值快照不可变';
COMMENT ON COLUMN deferral.deferral_id IS '延期记录自增主键';
COMMENT ON COLUMN deferral.equipment_id IS '所属设备标识';
COMMENT ON COLUMN deferral.defer_key IS '延期业务标识，设备内唯一（含历史记录，不可复用）';
