                .andExpect(jsonPath("$[0].deferKey").value("dk1"))
                .andExpect(jsonPath("$[0].status").value("REJECTED"))
                .andExpect(jsonPath("$[1].deferKey").value("dk2"))
                .andExpect(jsonPath("$[1].status").value("APPROVED"));
