    // ---------- 保养完成使待审批延期失效 ----------

    @Test
    void maintenance_expiresPendingDeferral() throws Exception {
        register("eq-exp", 100);
        addReading("eq-exp", "r-1", 1, "r1", "2026-01-01T10:00:00Z", 110, 201);
        applyDeferral("eq-exp", "d-1", "dk1", 20, "alice").andExpect(status().isCreated());

        // 保养完成先提交：待审批延期自动失效
